      this.emitir(reg, 'LanceRejeitado', { participante, valor, motivo: 'PARTICIPANTE_JA_LIDERA' }, ts);
      throw new HttpException({ aceito: false, motivo: 'PARTICIPANTE_JA_LIDERA' }, 422);
