        titulo: leilao.titulo,
        valor: leilao.maiorLance.valor,
        ocorridoEm: evento.ocorridoEm,
      });
    }
  }

  private reg(id: string): Registro {
    const r = this.leiloes.get(id);
    if (!r) throw new NotFoundException('Leilão não encontrado');
    return r;
  }
